// Love page - updated for compatibility
(function($) {
  "use strict";

  // Flowtime expected globals (referenced by all.min.js)
  window.player = {
    nojavascript: function() {
      $('.nojavascript').hide();
    }
  };
  window.onNavigation = function() {};

  // ---- BGM Music Control ----
  var audio = document.getElementById('bgmMusic');

  // Click-to-play (browser autoplay policy workaround)
  document.addEventListener('click', function() {
    if (audio && audio.paused) {
      audio.play().catch(function() {});
    }
  }, { once: true });

  // Play/Pause toggle buttons
  $('#on').on('click', function() {
    if (audio) {
      audio.pause();
      $(this).hide();
      $('#off').show();
    }
  });
  $('#off').on('click', function() {
    if (audio) {
      audio.play();
      $(this).hide();
      $('#on').show();
    }
  });

  // Progress bar update (if .progress element exists)
  if (audio) {
    audio.addEventListener('timeupdate', function() {
      var pct = (audio.currentTime / (audio.duration || 1)) * 100;
      $('.progress').css('width', Math.min(pct, 100) + '%');
    });
  }

  // ---- Image Preloader ----
  // Preload next few images for smoother browsing
  function preloadImages() {
    var images = $('img[data-src]').map(function() {
      return $(this).data('src');
    }).get();
    if (images.length === 0) return;
    var idx = 0;
    function loadNext() {
      if (idx >= images.length) return;
      var img = new Image();
      img.onload = function() { idx++; loadNext(); };
      img.src = images[idx];
    }
    loadNext();
  }
  preloadImages();

  // ---- Loading state ----
  $('.nojavascript').hide();

})(jQuery);
